 if(which==='team'){const team=m.staff||m.team||{},commitment=m.staffingCommitment,remaining=commitment?Math.max(0,commitment.committedUntil-m.clock):0,estimated=Math.floor((Number(team.engineers||0)+Number(team.support||0))*Number(commitment?.hourlyCents||0)*remaining/60),terms=commitment?`<p>${esc(remaining?translated(N_('provider.staff.commitment'),'Current team committed through minute {minute} ({remaining} minutes). Estimated remaining payroll at this size: {cost}.',{minute:commitment.committedUntil,remaining,cost:money(estimated)}):translated(N_('provider.staff.available'),'The current team commitment has ended. An increase starts a new 180-minute commitment.'))}</p>`:'';return `<p>${Number(team.engineers||0)} engineers · ${Number(team.support||0)} support staff</p>${terms}<form data-provider-form="staff"><label>Engineers<input name="engineers" type="number" min="0" max="20" value="${Number(team.engineers||0)}"></label><label>Support<input name="support" type="number" min="0" max="20" value="${Number(team.support||0)}"></label><button>Update staffing</button></form>`;}
